	if err == nil || !strings.Contains(err.Error(), "ghost") || upstreams != nil {
		t.Fatalf("empty graph: want naming error and nil results, got %v, %v", upstreams, err)
	}
	upstreams, err = Upstreams(nil, "ghost")
	if err == nil || !strings.Contains(err.Error(), "ghost") || upstreams != nil {
